<?php
namespace Satusehat\IntegrationSdk;
final class FhirClient {public function __construct(private Config $c,private TokenProvider $tokens){}public function requestOnce(string $method,string $rt,?string $id,?string $payload):array{$url=$this->c->fhirBaseUrl().'/'.$rt.($id?'/'.$id:'');$headers=[];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>strtoupper($method),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$this->c->timeoutSeconds,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$this->tokens->get(),'Accept: application/fhir+json, application/json','Content-Type: '.(strtoupper($method)==='PATCH'?'application/json-patch+json':'application/fhir+json')],CURLOPT_HEADERFUNCTION=>function($ch,$line)use(&$headers){$len=strlen($line);$p=explode(':',$line,2);if(count($p)===2)$headers[strtolower(trim($p[0]))]=trim($p[1]);return $len;}]);if($payload!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,$payload);$body=curl_exec($ch);if($body===false){$m=curl_error($ch);curl_close($ch);throw new \RuntimeException($m);} $status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);return['statusCode'=>$status,'body'=>(string)$body,'headers'=>$headers];}}
